package main

import (
	"fmt"
	"strconv"
	"strings"
	"unicode"
)

// TypeScript output (SPEC §5, §16). One file per module:
//
//   - `Problem`: a union discriminated by `kind` (the problem id) plus `Unknown`;
//   - one class per problem with an object-parameter constructor (required props enforce
//     presence and types), `detail()`, `logLine()`, `writeData()` and `fromEnvelope()`;
//   - `parse(body)`: typed value, `Unknown`, or `{kind:"not-problem"}` (never throws).
//
// Nothing generated extends Error and the generated file contains no `throw`: a decode
// mismatch goes through `rt.fail`, which is caught inside `rt.attempt`.

func init() {
	registerLang(&Lang{
		Name: "typescript",
		File: func(o Outputs) string {
			if o.TypeScript == nil {
				return ""
			}
			return o.TypeScript.File
		},
		Generate: func(m *Module, cfg *Config, o Outputs, src string) string {
			return GenerateTS(m, cfg, o.TypeScript, src)
		},
	})
}

// GenerateTS renders the TypeScript output for one module.
func GenerateTS(m *Module, cfg *Config, o *TSOut, source string) string {
	g := &tsGen{m: m, cfg: cfg, o: o}
	g.file(source)
	return g.b.String()
}

type tsGen struct {
	m   *Module
	cfg *Config
	o   *TSOut
	b   strings.Builder
}

func (g *tsGen) p(f string, a ...any) { fmt.Fprintf(&g.b, f, a...); g.b.WriteByte('\n') }

// tsQuoteUnits renders UTF-16 code units as an ASCII-only double-quoted JS string literal.
// Lone surrogates survive as \udXXX escapes.
func tsQuoteUnits(u []uint16) string {
	var b strings.Builder
	b.WriteByte('"')
	for _, c := range u {
		switch {
		case c == '"':
			b.WriteString(`\"`)
		case c == '\\':
			b.WriteString(`\\`)
		case c == '\n':
			b.WriteString(`\n`)
		case c == '\r':
			b.WriteString(`\r`)
		case c == '\t':
			b.WriteString(`\t`)
		case c < 0x20 || c > 0x7e:
			fmt.Fprintf(&b, `\u%04x`, c)
		default:
			b.WriteByte(byte(c))
		}
	}
	b.WriteByte('"')
	return b.String()
}

func tsQuote(s string) string { return tsQuoteUnits(stringToUnits(s)) }

func tsLowerFirst(s string) string {
	for i, r := range s {
		return string(unicode.ToLower(r)) + s[i+len(string(r)):]
	}
	return s
}

// tsDocText makes text safe inside a /** */ comment.
func tsDocText(s string) string {
	s = strings.ReplaceAll(s, "*/", "*\\/")
	return strings.ReplaceAll(s, "\n", "\n * ")
}

func (g *tsGen) doc(indent string, lines ...string) {
	var ls []string
	for _, l := range lines {
		if l != "" {
			ls = append(ls, tsDocText(l))
		}
	}
	if len(ls) == 0 {
		return
	}
	if len(ls) == 1 && !strings.Contains(ls[0], "\n") {
		g.p("%s/** %s */", indent, ls[0])
		return
	}
	g.p("%s/**", indent)
	for _, l := range ls {
		g.p("%s * %s", indent, l)
	}
	g.p("%s */", indent)
}

func (g *tsGen) isEnum(t FieldType) bool {
	if t.Kind != KRef {
		return false
	}
	nt := g.m.TypeByName(t.Ref)
	return nt != nil && nt.IsEnum
}

func (g *tsGen) tsType(t FieldType) string {
	switch t.Kind {
	case KString:
		return "string"
	case KInteger, KNumber:
		return "number"
	case KInt64:
		return "bigint"
	case KBoolean:
		return "boolean"
	case KDateTime:
		return "Date"
	case KArray:
		return "readonly " + g.tsType(*t.Items) + "[]"
	case KRef:
		return t.Ref
	}
	return "unknown"
}

// reachable returns the named types a public field of some problem (transitively) needs
// a writer and a decoder for. Helpers are emitted only for these, so the generated file has
// no unused local (noUnusedLocals stays on in the consuming project).
func (g *tsGen) reachable() map[string]bool {
	out := map[string]bool{}
	var visit func(t FieldType)
	visit = func(t FieldType) {
		switch t.Kind {
		case KArray:
			visit(*t.Items)
		case KRef:
			if out[t.Ref] {
				return
			}
			out[t.Ref] = true
			if nt := g.m.TypeByName(t.Ref); nt != nil && !nt.IsEnum {
				for _, f := range nt.Fields {
					visit(f.Type)
				}
			}
		}
	}
	for _, p := range g.m.Problems {
		for _, f := range p.PublicData() {
			visit(f.Type)
		}
	}
	return out
}

func (g *tsGen) file(source string) {
	g.p("// Code generated by problemgen %s. DO NOT EDIT.", toolVersion)
	g.p("// source: %s sha256:%s", source, g.m.Def.SHA256)
	g.p("/* eslint-disable */")
	g.p("")
	g.p("// Problems of %s/%s, module %s, version %s.", g.cfg.Platform, g.cfg.Service, g.m.Def.Module, g.m.Def.Version)
	g.p("// These are API-layer values: none of them is an Error and none is ever thrown.")
	g.p("// Domain code must not import this file (the consuming service enforces it with tsc + eslint).")
	g.p("")
	g.p("import * as rt from %s;", tsQuote(g.o.Runtime))
	g.p("")
	g.doc("", "The closed set of problems of this module, plus `Unknown` for anything else a client receives.", "Discriminated by `kind` (the problem id); switch on it and finish with `rt.unreachable(p)`.")
	var names []string
	for _, p := range g.m.Problems {
		names = append(names, Pascal(p.ID))
	}
	names = append(names, "Unknown")
	g.p("export type Problem = %s;", strings.Join(names, " | "))
	g.p("")
	g.doc("", "What `parse` returns: a problem (typed or `Unknown`), or `{ kind: \"not-problem\" }`.")
	g.p("export type Parsed = Problem | rt.NotProblem;")
	g.p("")
	reach := g.reachable()
	for _, t := range g.m.Types {
		g.namedType(t, reach[t.Name])
	}
	for _, p := range g.m.Problems {
		g.problem(p)
	}
	g.unknown()
	g.parse()
}

func (g *tsGen) namedType(t *NamedType, helpers bool) {
	g.doc("", t.Description)
	if t.IsEnum {
		var vs []string
		for _, v := range t.Values {
			vs = append(vs, strconv.Quote(v))
		}
		vals := tsLowerFirst(t.Name) + "Values"
		g.p("export const %s = [%s] as const;", vals, strings.Join(vs, ", "))
		g.p("export type %s = (typeof %s)[number];", t.Name, vals)
		g.p("/** Reports whether `v` is a declared value of %s. */", t.Name)
		g.p("export function is%s(v: unknown): v is %s {", t.Name, t.Name)
		g.p("  return typeof v === \"string\" && (%s as readonly string[]).includes(v);", vals)
		g.p("}")
		g.p("")
		return
	}
	g.p("export interface %s {", t.Name)
	for _, f := range t.Fields {
		g.doc("  ", f.Description, tsDeprecated(f.Deprecated))
		if f.Optional {
			g.p("  readonly %s?: %s | undefined;", f.Name, g.tsType(f.Type))
		} else {
			g.p("  readonly %s: %s;", f.Name, g.tsType(f.Type))
		}
	}
	g.p("}")
	g.p("")
	if !helpers {
		return
	}
	g.p("function _write_%s(w: rt.Writer, v: %s): void {", t.Name, t.Name)
	g.p("  w.beginObject();")
	for _, f := range t.Fields {
		g.writeField(f, "v."+f.Name, "  ")
	}
	g.p("  w.endObject();")
	g.p("}")
	g.p("")
	g.p("function _decode_%s(x: unknown): %s {", t.Name, t.Name)
	g.p("  const m = rt.fields(x);")
	g.p("  return {")
	for _, f := range t.Fields {
		g.p("    %s: %s,", f.Name, g.decodeCall("m", f))
	}
	g.p("  };")
	g.p("}")
	g.p("")
}

func tsDeprecated(reason string) string {
	if reason == "" {
		return ""
	}
	return "@deprecated " + reason
}

// writeValue emits the statements writing the value `expr` of type t.
func (g *tsGen) writeValue(expr string, t FieldType, indent string) {
	switch t.Kind {
	case KString:
		g.p("%sw.string(%s);", indent, expr)
	case KInteger:
		g.p("%sw.integer(%s);", indent, expr)
	case KInt64:
		g.p("%sw.int64(%s);", indent, expr)
	case KNumber:
		g.p("%sw.number(%s);", indent, expr)
	case KBoolean:
		g.p("%sw.bool(%s);", indent, expr)
	case KDateTime:
		g.p("%sw.dateTime(%s);", indent, expr)
	case KArray:
		g.p("%sw.beginArray();", indent)
		g.p("%sfor (const e of %s) {", indent, expr)
		g.writeValue("e", *t.Items, indent+"  ")
		g.p("%s}", indent)
		g.p("%sw.endArray();", indent)
	case KRef:
		if g.isEnum(t) {
			g.p("%sw.enum(%s, is%s(%s));", indent, expr, t.Ref, expr)
		} else {
			g.p("%s_write_%s(w, %s);", indent, t.Ref, expr)
		}
	}
}

func (g *tsGen) writeField(f *Field, expr, indent string) {
	if f.Private {
		return
	}
	if f.Optional {
		g.p("%sif (%s !== undefined) {", indent, expr)
		g.p("%s  w.key(%s);", indent, tsQuote(f.Name))
		g.writeValue(expr, f.Type, indent+"  ")
		g.p("%s}", indent)
		return
	}
	g.p("%sw.key(%s);", indent, tsQuote(f.Name))
	g.writeValue(expr, f.Type, indent)
}

// decodeFn returns a function expression (x: unknown) => T decoding a value of type t.
func (g *tsGen) decodeFn(t FieldType) string {
	switch t.Kind {
	case KString:
		return "rt.str"
	case KInteger:
		return "rt.integer"
	case KInt64:
		return "rt.int64"
	case KNumber:
		return "rt.number"
	case KBoolean:
		return "rt.bool"
	case KDateTime:
		return "rt.dateTime"
	case KArray:
		return "(x) => rt.arrayOf(x, " + g.decodeFn(*t.Items) + ")"
	case KRef:
		if g.isEnum(t) {
			return "(x) => rt.enumOf(x, " + tsLowerFirst(t.Ref) + "Values, " + tsQuote(t.Ref) + ")"
		}
		return "_decode_" + t.Ref
	}
	return "rt.fail"
}

func (g *tsGen) decodeCall(m string, f *Field) string {
	if f.Optional {
		return fmt.Sprintf("rt.optField(%s, %s, %s)", m, tsQuote(f.Name), g.decodeFn(f.Type))
	}
	return fmt.Sprintf("rt.field(%s, %s, %s)", m, tsQuote(f.Name), g.decodeFn(f.Type))
}

// zero is the value a parsed problem holds in a private field (it never travels).
func (g *tsGen) zero(f *Field) string {
	if f.Optional {
		return "undefined"
	}
	switch f.Type.Kind {
	case KString:
		return `""`
	case KInteger, KNumber:
		return "0"
	case KInt64:
		return "0n"
	case KBoolean:
		return "false"
	case KDateTime:
		return "new Date(0)"
	case KArray:
		return "[]"
	case KRef:
		if g.isEnum(f.Type) {
			return strconv.Quote(g.m.TypeByName(f.Type.Ref).Values[0])
		}
	}
	panic("problemgen: private field " + f.Name + " has a type that cannot be rendered in a log template (lint L217/L213 should have refused it)")
}

func (g *tsGen) templateExpr(p *Problem, part Part, forLog bool, val string) string {
	f := p.Field(part.Field)
	wrap := func(s string) string {
		if forLog {
			return "rt.logValue(" + s + ")"
		}
		return "rt.detailValue(" + s + ")"
	}
	switch {
	case part.Count:
		return "String(" + val + ".length)"
	case f.Type.Kind == KString:
		return wrap(val)
	case f.Type.Kind == KInteger || f.Type.Kind == KInt64 || f.Type.Kind == KNumber || f.Type.Kind == KBoolean:
		return "String(" + val + ")"
	case f.Type.Kind == KDateTime:
		return "rt.formatDateTime(" + val + ")"
	case g.isEnum(f.Type):
		return wrap(val)
	}
	return `""`
}

func (g *tsGen) renderTemplate(p *Problem, t *Template, forLog bool) {
	var parts []string
	for _, part := range t.Parts {
		if !part.IsPlaceholder() {
			parts = append(parts, tsQuote(part.Lit))
			continue
		}
		f := p.Field(part.Field)
		val := "this." + f.Name
		if f.Private {
			val = "this.#" + f.Name
		}
		e := g.templateExpr(p, part, forLog, val)
		if f.Optional {
			e = "(" + val + " === undefined ? " + tsQuote(part.Default) + " : " + e + ")"
		}
		parts = append(parts, e)
	}
	if len(parts) == 0 {
		parts = []string{`""`}
	}
	g.p("    return %s;", strings.Join(parts, " + "))
}

func (g *tsGen) problem(p *Problem) {
	n := Pascal(p.ID)
	cn := g.cfg
	g.doc("", fmt.Sprintf("%s: %s (%d). %s", strconv.Quote(p.ID), p.Title, p.Status, p.Description),
		"detail: "+p.DetailSrc, tsDeprecated(p.Deprecated))
	g.p("export class %s implements rt.ProblemValue {", n)
	g.p("  static readonly meta: rt.Meta = Object.freeze({ id: %s, title: %s, status: %d, recoverable: %v, platform: %s, service: %s, module: %s, version: %s });",
		tsQuote(p.ID), tsQuote(p.Title), p.Status, p.Recoverable, tsQuote(cn.Platform), tsQuote(cn.Service), tsQuote(g.m.Def.Module), tsQuote(g.m.Def.Version))
	g.p("  readonly kind = %s as const;", tsQuote(p.ID))
	for _, f := range p.Data {
		if f.Private {
			continue
		}
		g.doc("  ", f.Description, tsDeprecated(f.Deprecated))
		if f.Optional {
			g.p("  readonly %s: %s | undefined;", f.Name, g.tsType(f.Type))
		} else {
			g.p("  readonly %s: %s;", f.Name, g.tsType(f.Type))
		}
	}
	g.doc("  ", "The RFC 9457 `instance`, set by the API layer.")
	g.p("  readonly instance: string | undefined;")
	for _, f := range p.Data {
		if !f.Private {
			continue
		}
		t := g.tsType(f.Type)
		if f.Optional {
			t += " | undefined"
		}
		g.p("  readonly #%s: %s; // private: log only, never on the wire", f.Name, t)
	}
	g.p("  readonly #cause: unknown;")
	g.p("  #received: rt.Received | undefined = undefined;")
	g.p("")
	g.doc("  ", "Required fields are required properties; optional fields may be omitted.", "`cause` is for the log hook only and never reaches the wire.")
	g.p("  constructor(init: {")
	for _, f := range p.Data {
		if f.Optional {
			g.p("    %s?: %s | undefined;", f.Name, g.tsType(f.Type))
		} else {
			g.p("    %s: %s;", f.Name, g.tsType(f.Type))
		}
	}
	g.p("    instance?: string | undefined;")
	g.p("    cause?: unknown;")
	g.p("  }) {")
	for _, f := range p.Data {
		if f.Private {
			g.p("    this.#%s = init.%s;", f.Name, f.Name)
		} else {
			g.p("    this.%s = init.%s;", f.Name, f.Name)
		}
	}
	g.p("    this.instance = init.instance;")
	g.p("    this.#cause = init.cause;")
	g.p("  }")
	g.p("")
	g.p("  get meta(): rt.Meta {")
	g.p("    return %s.meta;", n)
	g.p("  }")
	g.p("")
	g.p("  problemCause(): unknown {")
	g.p("    return this.#cause;")
	g.p("  }")
	g.p("")
	g.p("  receivedType(): string | undefined {")
	g.p("    return this.#received?.type;")
	g.p("  }")
	g.p("")
	if p.RetryAfter != "" {
		g.p("  retryAfterSeconds(): number | undefined {")
		g.p("    return this.%s;", p.RetryAfter)
	} else {
		g.p("  retryAfterSeconds(): number | undefined {")
		g.p("    return undefined;")
	}
	g.p("  }")
	g.p("")
	g.p("  /** Renders the detail template (or returns the received detail). */")
	g.p("  detail(): string {")
	g.p("    if (this.#received !== undefined) return this.#received.detail;")
	g.renderTemplate(p, p.Detail, false)
	g.p("  }")
	g.p("")
	g.p("  /** Renders the log template. It may contain private fields; it is never sent. */")
	g.p("  logLine(): string {")
	g.renderTemplate(p, p.Log, true)
	g.p("  }")
	g.p("")
	g.p("  writeData(%s: rt.Writer): void {", map[bool]string{true: "w", false: "_w"}[len(p.PublicData()) > 0])
	if len(p.PublicData()) > 0 {
		g.p("    w.key(\"data\");")
		g.p("    w.beginObject();")
		for _, f := range p.Data {
			g.writeField(f, "this."+f.Name, "    ")
		}
		g.p("    w.endObject();")
	}
	g.p("  }")
	g.p("")
	g.p("  /** Decodes a received envelope of this problem (used by `parse`). */")
	g.p("  static fromEnvelope(e: rt.Envelope): %s {", n)
	if len(p.PublicData()) > 0 {
		g.p("    const m = rt.fields(e.data ?? {});")
	}
	g.p("    const p = new %s({", n)
	for _, f := range p.Data {
		if f.Private {
			g.p("      %s: %s,", f.Name, g.zero(f))
		} else {
			g.p("      %s: %s,", f.Name, g.decodeCall("m", f))
		}
	}
	g.p("      instance: e.instance,")
	g.p("    });")
	g.p("    p.#received = { type: e.type, detail: e.detail };")
	g.p("    return p;")
	g.p("  }")
	g.p("}")
	g.p("")
}

func (g *tsGen) unknown() {
	g.doc("", "A received problem this module does not define (another service, another version, an unknown id,",
		"or data that does not match). `reason` says which. Not an Error.")
	g.p("export class Unknown implements rt.ProblemValue {")
	g.p("  readonly kind = \"unknown\" as const;")
	g.p("  constructor(")
	g.p("    readonly envelope: rt.Envelope,")
	g.p("    readonly reason: string,")
	g.p("  ) {}")
	g.p("")
	g.p("  get meta(): rt.Meta {")
	g.p("    const e = this.envelope;")
	g.p("    const a = e.address;")
	g.p("    return {")
	g.p("      id: a?.id ?? \"\", title: e.title, status: e.status, recoverable: false,")
	g.p("      platform: a?.platform ?? \"\", service: a?.service ?? \"\", module: a?.module ?? \"\", version: a?.version ?? \"\",")
	g.p("    };")
	g.p("  }")
	g.p("")
	g.p("  get instance(): string | undefined {")
	g.p("    return this.envelope.instance;")
	g.p("  }")
	g.p("")
	g.p("  detail(): string {")
	g.p("    return this.envelope.detail;")
	g.p("  }")
	g.p("")
	g.p("  logLine(): string {")
	g.p("    return rt.logValue(\"unknown problem \" + this.envelope.type + \": \" + this.reason);")
	g.p("  }")
	g.p("")
	g.p("  problemCause(): unknown {")
	g.p("    return undefined;")
	g.p("  }")
	g.p("")
	g.p("  retryAfterSeconds(): number | undefined {")
	g.p("    return undefined;")
	g.p("  }")
	g.p("")
	g.p("  receivedType(): string {")
	g.p("    return this.envelope.type;")
	g.p("  }")
	g.p("")
	g.p("  /** An Unknown is for classification, not re-serialisation: it re-emits no data. */")
	g.p("  writeData(_w: rt.Writer): void {}")
	g.p("}")
	g.p("")
}

func (g *tsGen) parse() {
	mod := g.m.Def
	g.doc("", "Reads a received body. Returns `{ kind: \"not-problem\" }` only when it is not an RFC 9457 problem at all;",
		"anything this module does not define becomes `Unknown`. Never throws.")
	g.p("export function parse(body: string): Parsed {")
	g.p("  const e = rt.parseEnvelope(body);")
	g.p("  if (e.kind === \"not-problem\") return e;")
	g.p("  const a = e.address;")
	g.p("  if (a === undefined || a.platform !== %s || a.service !== %s || a.module !== %s || a.version !== %s) {",
		tsQuote(g.cfg.Platform), tsQuote(g.cfg.Service), tsQuote(mod.Module), tsQuote(mod.Version))
	g.p("    return new Unknown(e, %s);", tsQuote(fmt.Sprintf("not a problem of %s/%s/%s/%s", g.cfg.Platform, g.cfg.Service, mod.Module, mod.Version)))
	g.p("  }")
	g.p("  switch (a.id) {")
	for _, p := range g.m.Problems {
		n := Pascal(p.ID)
		g.p("    case %s: {", tsQuote(p.ID))
		g.p("      const r = rt.attempt(e, %d, %s.fromEnvelope);", p.Status, n)
		g.p("      return \"value\" in r ? r.value : new Unknown(e, r.reason);")
		g.p("    }")
	}
	g.p("  }")
	g.p("  return new Unknown(e, \"unknown id \" + JSON.stringify(a.id));")
	g.p("}")
}
